const arr = [
    '//sgt.sdgvg.com'
];
const randomIndex = Math.floor(Math.random() * arr.length);
const randomElement = arr[randomIndex];

var url = window.location.search;
var theRequest = new Object();
if (url.indexOf("?") != -1) {
    var str = url.substr(url.indexOf("?") + 1);
    str = str.replace(/&amp;/g, '&');
    var strs = str.split("&");
    for (var i = 0; i < strs.length; i++) {
        theRequest[strs[i].split("=")[0]] = decodeURI(strs[i].split("=")[1]);
    }


    if (typeof theRequest.code !== 'undefined' && theRequest.code !== null) {
        var xhr = new XMLHttpRequest();
        xhr.open('GET', `${randomElement}/api/find/key/${theRequest.code}`);
        xhr.onload = function () {
            if (xhr.status === 200) {
                if (xhr.responseText != '') {
                    var data = JSON.parse(xhr.responseText);
                    if (data.code == 200) {
                        gotoPage(data.data.url);
                        return false;
                    } else {
                        alert(data.msg);
                    }
                }
            }
        };
        xhr.send();
    }

}

function gotoPage(murl) {
    const url = `alipays://platformapi/startapp?appId=20000067&url=${encodeURIComponent(murl)}`;

    window.location.href = url;
}


